115	/* -------------------------------------------------------------------------- */
116	/*  Branch-name guard-rail                                                    */
117	/* -------------------------------------------------------------------------- */
118	
119	/** Refs this module is EVER allowed to touch on the destination remote — a
120	 *  `improve/<skill>-<date>` (generic skill, Chemin A of `apply.ts`) or
121	 *  `evolve/<date>` (meta-govern, Chemin B). Enforced by the module itself
122	 *  (not just documented convention): `transportImproveBranch` returns
123	 *  `rejected-branch-name` and issues ZERO git subprocess calls (fetch or
124	 *  push) whenever this fails. */
125	const ALLOWED_BRANCH_PREFIXES = ['improve/', 'evolve/'];
126	
127	/** A conservative git-ref-safety check beyond the prefix allow-list: no
128	 *  whitespace, no `:` (would corrupt the `src:dst` refspec strings this
129	 *  module builds), no `..` (git itself rejects this in a ref name, but
130	 *  failing fast here keeps the reason message specific to THIS module),
131	 *  and it must not end in `/` (git also rejects that, same rationale). */
132	function isSafeBranchRef(branch: string): boolean {
133	  if (branch.length === 0) return false;
134	  if (/\s/.test(branch)) return false;
135	  if (branch.includes(':')) return false;
136	  if (branch.includes('..')) return false;
137	  if (branch.endsWith('/')) return false;
138	  if (branch.startsWith('-')) return false;
139	  return true;
140	}
141	
142	function rejectionReasonForBranch(branch: string): string | undefined {
143	  const hasAllowedPrefix = ALLOWED_BRANCH_PREFIXES.some((p) => branch.startsWith(p));
144	  if (!hasAllowedPrefix) {
145	    return (
146	      `branche refusée : ${JSON.stringify(branch)} ne commence pas par ` +
147	      `${ALLOWED_BRANCH_PREFIXES.map((p) => JSON.stringify(p)).join(' ni ')} — ce module ne ` +
148	      'transporte jamais autre chose qu\'une branche improve/*|evolve/* du Banc d\'essai'
149	    );
150	  }
151	  if (!isSafeBranchRef(branch)) {
152	    return `branche refusée : ${JSON.stringify(branch)} n'est pas une référence git sûre (espace, ':', '..', '/' final, ou '-' initial)`;
153	  }
154	  return undefined;
155	}
