161	export interface TransportImproveBranchInput {
162	  /** Remote (URL or local path) the branch is fetched FROM — the CARGO
163	   *  remote in production. Never hardcoded by this module; always supplied
164	   *  by the caller. */
165	  cargoRemote: string;
166	  /** Remote (URL or local path) the branch is pushed TO — the real skills
167	   *  repo (`claude-skills`) in production. Never hardcoded by this module;
168	   *  always supplied by the caller. */
169	  destinationRemote: string;
170	  /** Full branch name, e.g. `improve/<skill>-<date>` or `evolve/<date>`.
171	   *  Validated by this function BEFORE any git subprocess is spawned — see
172	   *  `rejectionReasonForBranch`. */
173	  branch: string;
174	}
175	
176	export type TransportImproveBranchResult =
177	  /** Branch fetched from `cargoRemote` and pushed to `destinationRemote`
178	   *  under the same name (no `--force`, ever). */
179	  | { ok: true; kind: 'pushed'; branch: string; sha: string }
180	  /** IDEMPOTENT short-circuit: `destinationRemote` already carries `branch`
181	   *  at the exact same sha the cargo has — nothing was pushed. */
182	  | { ok: true; kind: 'already-up-to-date'; branch: string; sha: string }
183	  /** `branch` does not exist on `cargoRemote` at all. */
184	  | { ok: false; kind: 'source-branch-missing'; branch: string; reason: string }
185	  /** `branch` does not start with `improve/`/`evolve/`, or is not a safe git
186	   *  ref — rejected before any git subprocess ran. */
187	  | { ok: false; kind: 'rejected-branch-name'; branch: string; reason: string }
188	  /** `destinationRemote` already carries `branch` at a DIFFERENT sha and the
189	   *  push was rejected as a non-fast-forward (this module never retries with
190	   *  `--force`). */
191	  | { ok: false; kind: 'push-rejected'; branch: string; reason: string };
192	
193	/**
194	 * Re-pushes `branch` from `cargoRemote` to `destinationRemote`, unchanged,
195	 * under the same name. See the file header for the full rationale
196	 * (idempotence, temporary-clone choice, timeout idiom, branch-name
197	 * guard-rail).
198	 *
199	 * Guard-rails (enforced by this function itself, not just documented):
200	 *  - `branch` must start with `improve/` or `evolve/` and be a safe git
201	 *    ref — checked FIRST, before any git subprocess call (fetch OR push).
202	 *  - never `--force` on any push, under any circumstance.
203	 *  - every git subprocess is bounded by `GIT_TIMEOUT_MS` (60s, `SIGKILL` on
204	 *    timeout) — same idiom, same value, as `apply.ts`.
205	 *  - idempotent: if `destinationRemote` already has `branch` at the same sha
206	 *    as `cargoRemote`, nothing is pushed — the result says so explicitly
207	 *    (`kind: 'already-up-to-date'`), it is not just a log line.
208	 */
209	export async function transportImproveBranch(
210	  input: TransportImproveBranchInput,
211	): Promise<TransportImproveBranchResult> {
212	  const { cargoRemote, destinationRemote, branch } = input;
213	
214	  const rejectionReason = rejectionReasonForBranch(branch);
215	  if (rejectionReason !== undefined) {
216	    return { ok: false, kind: 'rejected-branch-name', branch, reason: rejectionReason };
217	  }
218	
219	  const scratch = await mkdtemp(path.join(os.tmpdir(), 'ws-improve-transport-'));
220	  try {
221	    // A plain (non-bare) empty repo is enough — this module only ever needs
222	    // to hold ONE fetched ref long enough to push it elsewhere; it never
223	    // checks anything out.
224	    git(['init', '-q', scratch], scratch);
225	    git(['config', 'user.email', 'workstation-evals@local'], scratch);
226	    git(['config', 'user.name', 'workstation-evals'], scratch);
227	
228	    // Fetch ONLY `branch` from the cargo remote, into a same-named local ref
229	    // — a missing branch makes `git fetch` exit non-zero (unlike
230	    // `ls-remote`), so `gitTry` here doubles as the existence check.
231	    const fetchResult = gitTry(
232	      ['fetch', '-q', cargoRemote, `${branch}:refs/heads/${branch}`],
233	      scratch,
234	    );
235	    if (!fetchResult.ok) {
236	      return {
237	        ok: false,
238	        kind: 'source-branch-missing',
239	        branch,
240	        reason:
241	          `branche ${branch} introuvable sur le remote cargo ${cargoRemote} : ` +
242	          (fetchResult.stderr || fetchResult.stdout || 'sortie vide'),
243	      };
244	    }
245	    const sourceSha = gitOut(['rev-parse', `refs/heads/${branch}`], scratch);
246	
247	    // Idempotence check — ask the DESTINATION remote directly (no clone of
248	    // it needed) whether it already carries this branch, and at what sha.
249	    const lsRemoteOut = gitOut(['ls-remote', '--heads', destinationRemote, branch], scratch);
250	    const destinationSha = parseLsRemoteHeadSha(lsRemoteOut);
251	
252	    if (destinationSha === sourceSha) {
253	      return { ok: true, kind: 'already-up-to-date', branch, sha: sourceSha };
254	    }
255	
256	    // Never `--force`: if the destination already has `branch` at a
257	    // DIFFERENT sha, a plain push is only accepted when it fast-forwards.
258	    // Anything else (destination diverged, or already up to date content-
259	    // wise but git still refuses for ref-log reasons) comes back as a typed
260	    // `push-rejected` failure instead of silently rewriting history there.
261	    const pushResult = gitTry(
262	      ['push', destinationRemote, `refs/heads/${branch}:refs/heads/${branch}`],
263	      scratch,
264	    );
265	    if (!pushResult.ok) {
266	      return {
267	        ok: false,
268	        kind: 'push-rejected',
269	        branch,
270	        reason:
271	          `push de ${branch} vers ${destinationRemote} refusé (non-fast-forward probable, ` +
272	          `sha destination actuel ${destinationSha ?? 'inconnu'}) : ` +
273	          (pushResult.stderr || pushResult.stdout || 'sortie vide'),
274	      };
275	    }
276	
277	    return { ok: true, kind: 'pushed', branch, sha: sourceSha };
278	  } finally {
279	    await rm(scratch, { recursive: true, force: true });
280	  }
281	}
