98	  includeSkillJobs: boolean;
99	  /** How many reviewed sessions / graded skill jobs were inspected in the
100	   *  window, BEFORE filtering out the ones with no findings — lets a reader
101	   *  tell "no findings on this window" apart from "no reviewed sessions at
102	   *  all in this window". */
103	  sourcesConsidered: { sessions: number; skillJobs: number };
104	  totalFindings: number;
105	  categories: LessonCategorySummary[];
106	}
