108	export interface AggregateLessonsOptions {
109	  /** `AAAA-MM-JJ`; defaults to `config/evals.json`'s `reviewSince`. */
110	  since?: string;
111	  /** Defaults to `true` — see module docstring for why. */
112	  includeSkillJobs?: boolean;
