115	function projectSlugForJob(job: SkillJob): string {
116	  return projectSlugFromRepoRoot(job.repoRoot);
117	}
118	
119	/** Group every finding from the given reviewed sessions / graded skill jobs
120	 *  by `category`. Each finding becomes one `LessonOccurrence` traced back to
121	 *  its source (`session:<sessionId>` or `skillJob:<jobId>` isn't stored as a
122	 *  single string — `sourceKind`+`sourceId` stay separate fields so a session
123	 *  and a job that happen to share an id text can never collide). */
124	function groupOccurrencesByCategory(
125	  sessionsInWindow: SessionReviewStamp[],
126	  skillJobsInWindow: SkillJob[],
127	): Map<string, LessonOccurrence[]> {
128	  const grouped = new Map<string, LessonOccurrence[]>();
129	  const push = (category: string, occ: LessonOccurrence) => {
130	    const list = grouped.get(category) ?? [];
131	    list.push(occ);
132	    grouped.set(category, list);
133	  };
134	
135	  for (const stamp of sessionsInWindow) {
136	    if (!stamp.review) continue;
137	    const occurredAt = stamp.reviewedAt ?? stamp.updatedAt;
138	    for (const f of stamp.review.findings) {
139	      push(f.category, {
140	        sourceKind: 'session',
141	        sourceId: stamp.sessionId,
142	        projectSlug: stamp.projectSlug,
143	        severity: f.severity,
144	        evidence: f.evidence,
145	        occurredAt,
146	      });
147	    }
148	  }
149	
150	  for (const job of skillJobsInWindow) {
151	    if (!job.review) continue;
152	    const occurredAt = job.review.gradedAt;
153	    for (const f of job.review.findings) {
154	      push(f.category, {
155	        sourceKind: 'skillJob',
156	        sourceId: job.id,
157	        projectSlug: projectSlugForJob(job),
158	        severity: f.severity,
159	        evidence: f.evidence,
160	        occurredAt,
161	      });
162	    }
163	  }
164	
165	  return grouped;
166	}
167	
168	function summarizeCategory(category: string, occs: LessonOccurrence[]): LessonCategorySummary {
169	  const distinctSources = Array.from(new Set(occs.map((o) => `${o.sourceKind}:${o.sourceId}`))).sort();
170	  const severities = (Array.from(new Set(occs.map((o) => o.severity))) as FindingSeverity[]).sort();
171	  const projects = Array.from(
172	    new Set(occs.map((o) => o.projectSlug).filter((p): p is string => Boolean(p))),
173	  ).sort();
174	  const sortedByDate = [...occs].sort((a, b) => a.occurredAt.localeCompare(b.occurredAt));
175	  const firstSeenAt = sortedByDate[0]?.occurredAt ?? '';
176	  const lastSeenAt = sortedByDate[sortedByDate.length - 1]?.occurredAt ?? '';
177	
178	  const hasP1 = severities.includes('P1');
179	  const recurring = distinctSources.length >= 2 || hasP1;
180	  const recurringReason: LessonCategorySummary['recurringReason'] = hasP1
181	    ? 'p1_finding'
182	    : distinctSources.length >= 2
183	      ? 'distinct_sources'
184	      : null;
185	
186	  return {
187	    category,
188	    occurrences: sortedByDate,
189	    count: occs.length,
190	    severities,
191	    projects,
192	    distinctSources,
193	    firstSeenAt,
194	    lastSeenAt,
195	    recurring,
196	    recurringReason,
197	  };
198	}
199	
200	/**
201	 * Aggregate `review.findings` across reviewed sessions (and, unless disabled,
202	 * graded skill jobs) by `category`, over `[since, now]`. Pure read — see
203	 * module docstring for the exact set of calls this makes.
204	 */
205	export async function aggregateLessons(
206	  options: AggregateLessonsOptions = {},
207	): Promise<LessonsAggregate> {
208	  const includeSkillJobs = options.includeSkillJobs ?? true;
209	  const since = options.since ?? (await loadEvalsConfig()).reviewSince;
210	
211	  const sessionStamps = await listSessionStamps({ state: ['reviewed'] });
212	  const skillJobs = includeSkillJobs ? await listSkillJobs() : [];
213	
214	  const sessionsInWindow = sessionStamps.filter((s) => (s.reviewedAt ?? s.updatedAt) >= since);
215	  const skillJobsInWindow = skillJobs.filter((j) => j.review !== undefined && j.review.gradedAt >= since);
216	
217	  const grouped = groupOccurrencesByCategory(sessionsInWindow, skillJobsInWindow);
218	
219	  const categories: LessonCategorySummary[] = Array.from(grouped.entries())
220	    .map(([category, occs]) => summarizeCategory(category, occs))
221	    .sort((a, b) => b.count - a.count || a.category.localeCompare(b.category));
222	
223	  const totalFindings = categories.reduce((sum, c) => sum + c.count, 0);
224	
225	  return {
226	    since,
227	    generatedAt: new Date().toISOString(),
228	    includeSkillJobs,
229	    sourcesConsidered: {
230	      sessions: sessionsInWindow.length,
231	      skillJobs: skillJobsInWindow.length,
232	    },
233	    totalFindings,
234	    categories,
235	  };
236	}
