291	/** Recursively snapshot every file's relative path + content under `dir`,
292	 *  sorted, so the comparison is stable regardless of directory read order. */
293	async function snapshotDir(dir: string): Promise<Record<string, string>> {
294	  const out: Record<string, string> = {};
295	  async function walk(current: string): Promise<void> {
296	    let entries;
297	    try {
298	      entries = await readdir(current, { withFileTypes: true });
299	    } catch {
300	      return;
301	    }
302	    for (const entry of entries) {
303	      const full = path.join(current, entry.name);
304	      if (entry.isDirectory()) {
305	        await walk(full);
306	      } else if (entry.isFile()) {
307	        out[path.relative(dir, full)] = await readFile(full, 'utf8');
308	      }
309	    }
310	  }
311	  await walk(dir);
312	  return out;
313	}
