 *  OVERRIDE) is ever allowed to take. */
const NIGHT_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/** Throws if `nightDate` is defined but not `AAAA-MM-JJ` — called before any
 *  conversation/proposal write, per the file header's NIGHTDATE OVERRIDE note. */
function assertValidNightDate(nightDate: string): void {
  if (!NIGHT_DATE_RE.test(nightDate)) {
    throw new Error(`nightDate invalide (attendu "AAAA-MM-JJ") : ${nightDate}`);
  }
}

