  const m = /^improvement-(\d+)-/.exec(proposal.id);
  const ms = m ? Number(m[1]) : Date.parse(proposal.updatedAt);
  const date = new Date(Number.isFinite(ms) ? ms : Date.now());
  return date.toISOString().slice(0, 10);
}

